import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    original = torch.rand((1, 16, 16), generator=ctx.rng.torch)
    mask = torch.zeros((1, 16, 16))
    mask[:, 4:12, 4:12] = 1
    corrupted = original * (1 - mask) + 0.5 * mask
    return {"inputs": synth.Tensor(corrupted), "original": synth.Tensor(original), "mask": synth.Tensor(mask)}
dataset = synth.Spec("draem-example", generator=samples, size=4, splits={"train": 1.0}, seed=11, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class DRAEMModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = nn.Conv2d(1, 3, kernel_size=1)
    def forward(self, inputs):
        outputs = self.network(inputs)
        return {"reconstruction": outputs[:, :1], "logits": outputs[:, 1:]}
trainer = Trainer(DRAEMModel(), train, recipe="structured-objective", recipe_config={"loss": "draem", "bindings": {"logits_or_prediction": {"output": "logits"}, "targets": {"batch": "mask"}, "original": {"batch": "original"}, "reconstruction": {"output": "reconstruction"}}}, batch_size=2, max_epochs=1, device="cpu")
trainer.fit()
